<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {stocksWindow,stocksQuote,stocksStory,stocksCurrent,stocksChart,stocksSearch,stocksCapabilities} from './stocks-state.js';
 import {stocksMenus} from './stocks-menus.js';
 import {createStocksNativeView} from './stocks-native-view.js';
 import './stocks.css';
 let {state: stocksState,profile,windowId,execute,registerView,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state(''),hover=$state(null),dragStart=$state(null),dragEnd=$state(null),originalState,originalProfile,originalWindowId,retired=false;
 const session=$derived(stocksWindow(stocksState,windowId)),cap=$derived(stocksCapabilities(profile,stocksState.preferences.region)),quote=$derived(stocksQuote(stocksState,session?.selectedId)),currentQuote=$derived(stocksCurrent(stocksState,quote)),story=$derived(stocksStory(stocksState,session?.storyId)),points=$derived(stocksChart(stocksState,quote)),menus=$derived(stocksMenus(profile,stocksState,windowId));
 const rows=$derived(session?.query.trim()?stocksSearch(stocksState,session.query):stocksState.watchlist.map(id=>stocksQuote(stocksState,id))),stories=$derived(stocksState.stories.filter(s=>s.publishedAt<=stocksState.runtime.refreshedAt&&(!quote||s.symbolIds.includes(quote.id))));
 const chart=$derived(chartData(points)),point=$derived(hover===null?null:points[hover]),rangeFrom=$derived(dragStart===null?null:points[Math.min(dragStart,dragEnd??dragStart)]),rangeTo=$derived(dragStart===null?null:points[Math.max(dragStart,dragEnd??dragStart)]);
 function owned(){return !retired&&root?.isConnected&&stocksState===originalState&&profile===originalProfile&&windowId===originalWindowId;}
 async function command(name,payload={}){if(!owned()||!available||!active)return;const result=await execute(`stocks.${name}`,{windowId},payload);if(owned())message=result?.status==='applied'?'':result?.error?.message??'Actual local market operation unavailable.';return result;}
 const money=value=>value==null?'—':value.toFixed(2),signed=value=>`${value>=0?'+':''}${value.toFixed(2)}`,compact=n=>n>=1e9?`${(n/1e9).toFixed(2)}B`:n>=1e6?`${(n/1e6).toFixed(2)}M`:String(n),date=at=>new Date(at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
 function chartData(samples){if(!samples.length)return {path:'',area:'',min:0,max:1};const low=Math.min(...samples.map(p=>p.price)),high=Math.max(...samples.map(p=>p.price)),pad=Math.max(.1,(high-low)*.1),min=low-pad,max=high+pad,start=samples[0].at,end=samples.at(-1).at,coords=samples.map(p=>[12+(p.at-start)/Math.max(1,end-start)*548,12+(max-p.price)/(max-min)*176]),path=coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');return {path,area:`${path} L560,188 L12,188 Z`,min,max};}
 function pointer(event){if(!points.length)return;const rect=event.currentTarget.getBoundingClientRect(),fraction=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),at=points[0].at+fraction*(points.at(-1).at-points[0].at);let index=0;for(let i=1;i<points.length;i++)if(Math.abs(points[i].at-at)<Math.abs(points[index].at-at))index=i;hover=index;if(dragStart!==null)dragEnd=index;}
 function reorder(id,step){const ids=[...stocksState.watchlist],index=ids.indexOf(id),next=index+step;if(next<0||next>=ids.length)return;[ids[index],ids[next]]=[ids[next],ids[index]];command('watchlist.reorder',{symbolIds:ids});}
 let watchDrag=null;
 function beginWatchDrag(event,row){if(!owned()||!session?.editing||session.query||!stocksState.watchlist.includes(row.id)){event.preventDefault();return;}watchDrag={root,state: stocksState,row,session,signature:JSON.stringify(stocksState.watchlist)};event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',row.id);}
 function dropWatchDrag(event,row){event.preventDefault();const drag=watchDrag;watchDrag=null;if(!drag||!owned()||drag.root!==root||drag.state!==stocksState||drag.session!==session||stocksQuote(stocksState,drag.row.id)!==drag.row||!session.editing||session.query||JSON.stringify(stocksState.watchlist)!==drag.signature)return;const ids=[...stocksState.watchlist],from=ids.indexOf(drag.row.id),to=ids.indexOf(row.id);if(from<0||to<0||from===to)return;ids.splice(from,1);ids.splice(to,0,drag.row.id);command('watchlist.reorder',{symbolIds:ids});}
 function key(event){if(!owned()||!active||!available)return;if(event.key==='Escape'){command('sheet',{sheet:'none'});command('story.back');}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='s'&&story){event.preventDefault();command('story.saveNews');}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='r'){event.preventDefault();command('refresh');}}
 onMount(()=>{originalState=stocksState;originalProfile=profile;originalWindowId=windowId;const view=createStocksNativeView({getRoot:()=>root,getState:()=>stocksState,windowId,available:()=>owned()&&available&&active,tick,getMenus:()=>stocksMenus(profile,stocksState,windowId)});registerView(windowId,view);return()=>{retired=true;view.destroy();registerView(originalWindowId,null,view);};});
</script>
<section bind:this={root} class="stocks-app" class:mojave={cap.mojave} class:golden={cap.golden} class:equivalent={!cap.native} class:windows={cap.windows} class:inactive={!active} data-stocks-window-id={windowId} data-profile={profile.id} aria-label={cap.label} role="region" tabindex="-1" onkeydown={key}>
 <header class="stocks-titlebar">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}<button data-stocks-control="back" title="Back to business headlines" disabled={!story} onclick={()=>command('story.back')}>‹</button><strong>{cap.label}</strong><button data-stocks-control="share" title="Share story" disabled={!story||!cap.nativeReader} onclick={()=>command('story.share')}>↥</button></header>
 <nav class="stocks-local-menus" aria-label="Application menus">{#each menus as menu}<button data-stocks-control={`menu:${menu.id}`} aria-haspopup="menu" aria-expanded={session?.menu===menu.id} onclick={()=>command(session?.menu===menu.id?'menu.close':'menu.open',session?.menu===menu.id?{}:{menuId:menu.id})}>{menu.label}</button>{/each}</nav>
 {#if session?.menu}<div class="stocks-menu" role="menu" aria-label={session.menu}>{#each menus.find(m=>m.id===session.menu)?.items??[] as item}<button role="menuitem" disabled={!item.enabled} data-stocks-control={`menuitem:${item.id}`} onclick={async()=>{await command('menu.close');if(item.request)execute(item.request.command,item.request.target,item.request.payload);}}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 {#if !cap.native||cap.golden}<p class="stocks-disclosure">{cap.disclosure}</p>{/if}
 <div class="stocks-workspace" inert={!available||!active||session?.sheet!=='none'||!!session?.removeId}>
  <aside class="stocks-sidebar"><div class="stocks-search"><input type="search" placeholder="Search" aria-label="Search ticker symbols" data-stocks-control="search" maxlength="4096" value={session?.query??''} oninput={event=>command('search',{query:event.currentTarget.value})}/></div><button class="stocks-business" data-stocks-control="business" class:selected={!quote&&!story} onclick={()=>command('business')}><strong>BUSINESS NEWS</strong><span>From local publishers</span></button>{#if !cap.mojave}<div class="stocks-symbols-heading">My Symbols</div>{/if}
   <div class="stocks-watchlist" data-stocks-area="watchlist">{#each rows as row}{@const price=stocksCurrent(stocksState,row)}{@const small=chartData(stocksChart(stocksState,row,'1D'))}<div class="stocks-watchrow" class:selected={quote?.id===row.id} data-stocks-symbol={row.id} draggable={session?.editing&&!session.query&&stocksState.watchlist.includes(row.id)} ondragstart={event=>beginWatchDrag(event,row)} ondragover={event=>{if(watchDrag)event.preventDefault();}} ondrop={event=>dropWatchDrag(event,row)} ondragend={()=>{watchDrag=null;}}><button class="stocks-symbol-button" data-stocks-control={`symbol:${row.id}`} onclick={()=>{hover=null;command('select',{symbolId:row.id});}}><span class="stocks-symbol-name"><strong>{row.id}</strong><small>{row.name}</small></span><svg viewBox="0 0 572 200" aria-hidden="true" class:loss={price?.change<0}><path d={small.path}/></svg><span class="stocks-row-price"><strong>{money(price?.price)}</strong><span class:negative={price?.change<0}>{stocksState.preferences.display==='market-cap'?compact(price?.marketCap??0):stocksState.preferences.display==='percent'?`${signed(price?.percent??0)}%`:signed(price?.change??0)}</span></span></button>{#if session?.editing}<div class="stocks-row-edit"><button data-stocks-control={`remove:${row.id}`} onclick={()=>command('watchlist.remove',{symbolId:row.id,confirm:false})}>−</button><button title="Move up" disabled={stocksState.watchlist.indexOf(row.id)<=0} onclick={()=>reorder(row.id,-1)}>↑</button><button title="Move down" disabled={stocksState.watchlist.indexOf(row.id)>=stocksState.watchlist.length-1} onclick={()=>reorder(row.id,1)}>↓</button></div>{/if}{#if session?.query&&!stocksState.watchlist.includes(row.id)}<button data-stocks-control={`add:${row.id}`} class="stocks-add" title={`Add ${row.id} to watchlist`} onclick={()=>command('watchlist.add',{symbolId:row.id})}>＋</button>{/if}</div>{/each}{#if !rows.length}<p class="stocks-empty">No local symbols match.</p>{/if}</div>
   <footer><span>Local authored quotes</span><button data-stocks-control="watchlist:edit" onclick={()=>command('watchlist.edit',{editing:!session?.editing})}>{session?.editing?'Done':'☷'}</button></footer>
  </aside>
  <main class="stocks-detail" data-stocks-area={story?'reader':'detail'}>
   {#if story}<article class="stocks-reader" data-stocks-story={story.id}><div class="stocks-publisher">{story.publisher}</div><h1>{story.title}</h1><p class="stocks-byline">{story.author} · {date(story.publishedAt)} · Authored local edition</p><div class="stocks-article-image" aria-hidden="true"><svg viewBox="0 0 640 240"><rect width="640" height="240" fill="#dce6e9"/><path d="M0 200 L140 105 L255 185 L380 62 L520 148 L640 91 L640 240 L0 240Z" fill="#829eaa"/><path d="M0 220 L175 172 L300 225 L445 165 L640 210 L640 240 L0 240Z" fill="#4b6b75"/><circle cx="520" cy="47" r="20" fill="#f5e8c6"/></svg></div>{#each story.paragraphs as paragraph}<p>{paragraph}</p>{/each}<div class="stocks-reader-actions"><button data-stocks-control="reader:share" disabled={!cap.nativeReader} onclick={()=>command('story.share')}>Share Story</button><button data-stocks-control="reader:save" disabled={!cap.nativeReader} onclick={()=>command('story.saveNews')}>Save Story to News</button><button data-stocks-control="reader:notify" onclick={()=>command('notify',{kind:'stocks-story',recordId:story.id})}>Post Local Story Alert</button></div>{#if !cap.nativeReader}<p class="stocks-region-note">Mojave native in-app sharing and News saving are available only in the US, UK and Australia. This offline article is an explicitly local reader equivalent for this region.</p>{/if}</article>
   {:else}
    {#if quote&&currentQuote}<div class="stocks-quote-header"><div><div class="stocks-quote-name"><h1>{quote.id}</h1><span>{quote.name}</span>{#if !stocksState.watchlist.includes(quote.id)}<button data-stocks-control="detail:add" onclick={()=>command('watchlist.add',{symbolId:quote.id})}>＋</button>{/if}</div><small>{quote.exchange} · {quote.currency} · FICTIONAL</small></div><div class="stocks-current-price"><strong>{money(currentQuote.price)}</strong><span class:negative={currentQuote.change<0}>{signed(currentQuote.change)}</span><small>{new Date(currentQuote.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'UTC'})} UTC</small></div></div>
    <div class="stocks-range" aria-label="Chart range">{#each cap.ranges as range}<button data-stocks-control={`range:${range}`} aria-pressed={stocksState.range===range} class:selected={stocksState.range===range} onclick={()=>{hover=null;command('range',{range});}}>{range}</button>{/each}</div>
    <div class="stocks-chart-caption" aria-live="polite">{#if rangeFrom&&rangeTo}{date(rangeFrom.at)} – {date(rangeTo.at)} · {signed(rangeTo.price-rangeFrom.price)} ({signed((rangeTo.price-rangeFrom.price)/rangeFrom.price*100)}%){:else if point}{date(point.at)} · {money(point.price)}{:else}Original authored observations · {stocksState.range}{/if}</div>
    <div class="stocks-chart" class:loss={currentQuote.change<0}><svg viewBox="0 0 610 212" role="img" aria-label={`${quote.name} ${stocksState.range} original price chart`} onpointermove={pointer} onpointerleave={()=>{hover=null;dragStart=null;dragEnd=null;}} onpointerdown={event=>{pointer(event);dragStart=hover;dragEnd=hover;event.currentTarget.setPointerCapture(event.pointerId);}} onpointerup={()=>{dragStart=null;dragEnd=null;}}><defs><linearGradient id={`stocks-fill-${windowId}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="currentColor" stop-opacity=".27"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs>{#each [12,56,100,144,188] as y}<path class="stocks-gridline" d={`M12 ${y} H560`}/>{/each}{#each [12,149,286,423,560] as x}<path class="stocks-gridline" d={`M${x} 12 V188`}/>{/each}<path d={chart.area} fill={`url(#stocks-fill-${windowId})`} stroke="none"/><path d={chart.path} fill="none" stroke="currentColor" stroke-width="1.7"/>{#each [chart.max,(chart.min+chart.max)/2,chart.min] as price,i}<text x="572" y={18+i*84}>{money(price)}</text>{/each}{#if point}<path class="stocks-crosshair" d={`M${12+(point.at-points[0].at)/Math.max(1,points.at(-1).at-points[0].at)*548} 12 V188`}/>{/if}</svg><div class="stocks-chart-axis"><span>{points.length?date(points[0].at):''}</span><span>{points.length?date(points.at(-1).at):''}</span></div></div>
    <dl class="stocks-details"><div><dt>Open</dt><dd>{money(currentQuote.open)}</dd><dt>High</dt><dd>{money(currentQuote.high)}</dd><dt>Low</dt><dd>{money(currentQuote.low)}</dd></div><div><dt>Vol</dt><dd>{compact(currentQuote.volume)}</dd><dt>P/E</dt><dd>{quote.pe.toFixed(2)}</dd><dt>Mkt Cap</dt><dd>{compact(currentQuote.marketCap)}</dd></div><div><dt>Yield</dt><dd>{(quote.dividend/currentQuote.price*100).toFixed(2)}%</dd><dt>Sector</dt><dd>{quote.sector}</dd><dt>Source</dt><dd>Authored</dd></div></dl>
    <div class="stocks-source-actions"><button data-stocks-control="refresh" onclick={()=>command('refresh')}>Refresh</button><button data-stocks-control="quote:notify" onclick={()=>command('notify',{kind:'stocks-price',recordId:quote.id})}>Post Local Quote Alert</button></div>
    {:else}<h1 class="stocks-business-title">Business News</h1><p class="stocks-local-note">Complete local business reporting · no subscriptions or network</p>{/if}
    <div class="stocks-news-grid">{#each stories as item,i}<button class="stocks-story-card" data-stocks-story={item.id} data-stocks-control={`story:${item.id}`} onclick={()=>command('story.open',{storyId:item.id})}><div class="stocks-story-art" class:alternate={i%2===1}><svg viewBox="0 0 260 130" aria-hidden="true"><rect width="260" height="130" fill="currentColor"/><path d="M0 115 L55 55 L97 95 L160 24 L260 82 L260 130 L0 130Z" fill="#fff" opacity=".35"/><path d="M0 115 L85 90 L125 114 L200 73 L260 110 L260 130 L0 130Z" fill="#fff" opacity=".2"/></svg></div><small>{item.publisher}</small><strong>{item.title}</strong><span>{date(item.publishedAt)}</span></button>{/each}</div>
   {/if}
  </main>
 </div>
 {#if session?.sheet!=='none'||session?.removeId}<div class="stocks-sheet-backdrop"><section class="stocks-sheet" role="dialog" aria-modal="true" aria-label={session?.removeId?'Remove Symbol':session?.sheet==='preferences'?'Stocks Preferences':'Stocks Help'}>{#if session?.removeId}<h2>Remove {session.removeId}?</h2><p>This removes the original symbol from the shared watchlist and retires its active local quote alerts. Its authored price history remains searchable.</p><button data-stocks-control="remove:confirm" onclick={()=>command('watchlist.remove',{symbolId:session.removeId,confirm:true})}>Remove</button><button data-stocks-control="remove:cancel" onclick={()=>command('watchlist.edit',{editing:session.editing})}>Cancel</button>{:else if session?.sheet==='preferences'}<h2>{cap.mojave?'Preferences':'Settings'}</h2><label>Watchlist display<select data-stocks-control="preferences:display" value={stocksState.preferences.display} onchange={event=>command('preferences',{values:{...stocksState.preferences,display:event.currentTarget.value}})}><option value="change">Price Change</option><option value="percent">Percentage Change</option><option value="market-cap">Market Capitalization</option></select></label><label>Local edition<select data-stocks-control="preferences:region" value={stocksState.preferences.region} onchange={event=>command('preferences',{values:{...stocksState.preferences,region:event.currentTarget.value}})}><option value="US">United States</option><option value="GB">United Kingdom</option><option value="AU">Australia</option><option value="CA">Canada</option><option value="OTHER">Other Region</option></select></label><label><input type="checkbox" data-stocks-control="preferences:notifications" checked={stocksState.preferences.notifications} onchange={event=>command('preferences',{values:{...stocksState.preferences,notifications:event.currentTarget.checked}})}/>Enable authored local alerts</label><p>These offline fixture controls do not sign in, reset an advertising identifier, or subscribe to a live market feed.</p><button data-stocks-control="sheet:done" onclick={()=>command('sheet',{sheet:'none'})}>Done</button>{:else}<h2>Stocks · Local Market</h2><p>{cap.disclosure}</p><p>Search by ticker, name or sector. Edit the watchlist to remove or reorder symbols. Every range plots its original timestamped observations; hover for the exact price or drag to compare two points. Refresh and widgets use the same authored scene clock, never random prices.</p><p>Read the complete business articles, share their actual text to local native destinations, or save an actual story in News. Posting an alert creates one genuine shared notification with an original source link.</p><button data-stocks-control="sheet:done" onclick={()=>command('sheet',{sheet:'none'})}>Done</button>{/if}</section></div>{/if}
 <footer class="stocks-status" role="status">{message||`Authored offline market · ${date(stocksState.runtime.refreshedAt)} · single canonical watchlist and clock`}</footer>
</section>
